// Fuse init/drain into the MAC loop. Keep PE UNROLL + SIMD UNROLL.
compute_k0: for (int k0 = 0; k0 < K; k0 += SIMD) {
  compute_j: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
    pe_mac: for (int p = 0; p < PE; ++p) {
#pragma HLS UNROLL
      data_t partial = /* SIMD adder tree */;
      data_t acc = (k0 == 0) ? partial : (Crow[p][j] + partial);
      Crow[p][j] = acc;
      if (k0 == K - SIMD) local_C[i0 + p][j] = acc;
    }
  }
}

// PE array kept. Tile loop AROUND DATAFLOW. Ping-pong A/C tiles. Not mm_pe FIFOs.
static void load_A_tile(data_t A[I][K], data_t Atile[PE][K], int i0) {
#pragma HLS INLINE off
  for (int p = 0; p < PE; ++p)
    for (int k = 0; k < K; ++k) {
#pragma HLS PIPELINE II=1
      Atile[p][k] = A[i0 + p][k];
    }
}
static void compute_tile(data_t Atile[PE][K], data_t local_B[J][K], data_t Ctile[PE][J]); // fused PE×SIMD nest
static void store_C_tile(data_t C[I][J], data_t Ctile[PE][J], int i0);
